    elif days_left == 1:
        headline = 'T-1 day left until WeAreDevelopers. Our product launch is soon. Get hype!'
    else:
        headline = f'T-{days_left} days left until WeAreDevelopers. Our product launch is soon. Get hype!'
    print(today, headline)
